import com.apexbooks.backup.StreamingEncryptedBackup;
import com.fasterxml.jackson.core.*;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import javax.crypto.*;import javax.crypto.spec.*;

public class StreamingBackupTest {
 static final char[] PASSWORD="cross-platform-test-only".toCharArray();static int checks;
 static void check(boolean condition,String label){if(!condition)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 static byte[] digest(Path path)throws Exception {MessageDigest d=MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(path)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}return d.digest();}
 static byte[] key(char[] password,byte[] salt)throws Exception {var spec=new PBEKeySpec(password,salt,250000,256);try{return SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();}finally{spec.clearPassword();}}
 static byte[] legacy(byte[] plain,char[] password)throws Exception {byte[] salt=new byte[16],iv=new byte[12];new SecureRandom().nextBytes(salt);new SecureRandom().nextBytes(iv);var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(key(password,salt),"AES"),new GCMParameterSpec(128,iv));String json="{\"format\":\"apex-encrypted-backup\",\"version\":1,\"salt\":\""+Base64.getEncoder().encodeToString(salt)+"\",\"iv\":\""+Base64.getEncoder().encodeToString(iv)+"\",\"ciphertext\":\""+Base64.getEncoder().encodeToString(cipher.doFinal(plain))+"\"}";return json.getBytes(StandardCharsets.UTF_8);}
 static void fails(byte[] envelope,char[] password,File dir,long max,String label)throws Exception {boolean failed=false;try(var ignored=StreamingEncryptedBackup.decrypt(new ByteArrayInputStream(envelope),password,dir,max,()->false)){}catch(Exception e){failed=true;}check(failed,label);check(Objects.requireNonNull(dir.list()).length==0,label+" staging cleanup");}
 public static void main(String[] args)throws Exception {
  Path root=Path.of(args[0]);Files.createDirectories(root);File staging=Files.createTempDirectory(root,"private-").toFile();long maximum=320L*1024*1024;
  try {
   byte[] plain="Synthetic portable backup payload \u20b9 \ud83d\udd12".getBytes(StandardCharsets.UTF_8),old=legacy(plain,PASSWORD);
   Files.write(root.resolve("android-compatible-v1.json"),old);Files.write(root.resolve("android-compatible-v1.bin"),plain);
   char[] unicode="cross-platform-₹-test-🔒".toCharArray();Files.write(root.resolve("android-unicode-v1.json"),legacy(plain,unicode));
   try(var decoded=StreamingEncryptedBackup.decrypt(new ByteArrayInputStream(old),PASSWORD,staging,maximum,()->false)){check(Arrays.equals(plain,Files.readAllBytes(decoded.file().toPath())),"legacy Android-compatible JCE writer decrypts");}
   try(var encrypted=StreamingEncryptedBackup.encrypt(new ByteArrayInputStream(plain),PASSWORD,staging,maximum,()->false);var bytes=new FileInputStream(encrypted.file());var decoded=StreamingEncryptedBackup.decrypt(bytes,PASSWORD,staging,maximum,()->false)){check(Arrays.equals(plain,Files.readAllBytes(decoded.file().toPath())),"new encrypted-v1 streaming roundtrip");Files.copy(encrypted.file().toPath(),root.resolve("android-streaming-v1.json"),StandardCopyOption.REPLACE_EXISTING);}
   for(String fixture:new String[]{"csharp-legacy-v1.json","csharp-escaped-reordered-v1.json","csharp-legacy-unicode-password-v1.json"}){Path source=root.resolve(fixture);if(Files.exists(source)){char[] pass=fixture.contains("unicode")?unicode:PASSWORD;try(var in=Files.newInputStream(source);var decoded=StreamingEncryptedBackup.decrypt(in,pass,staging,maximum,()->false)){Path expected=root.resolve("csharp-legacy-v1.bin");check(Arrays.equals(Files.readAllBytes(expected),Files.readAllBytes(decoded.file().toPath())),fixture+" crosswriter");}}}
   String text=new String(old,StandardCharsets.UTF_8);String escaped=text.replace("+","\\u002B").replace("/","\\/");try(var decoded=StreamingEncryptedBackup.decrypt(new ByteArrayInputStream(escaped.getBytes(StandardCharsets.UTF_8)),PASSWORD,staging,maximum,()->false)){check(Arrays.equals(plain,Files.readAllBytes(decoded.file().toPath())),"escaped base64 remains compatible");}
   byte[] escapePlain=new byte[32768];new Random(44).nextBytes(escapePlain);String escapeEnvelope=new String(legacy(escapePlain,PASSWORD),StandardCharsets.UTF_8);int begin=escapeEnvelope.indexOf("\"ciphertext\":\"")+14;String encoded=escapeEnvelope.substring(begin,escapeEnvelope.length()-2);StringBuilder allEscaped=new StringBuilder();for(char c:encoded.toCharArray())allEscaped.append(String.format("\\u%04x",(int)c));String expanded=escapeEnvelope.substring(0,begin)+allEscaped+"\"}";try(var decoded=StreamingEncryptedBackup.decrypt(new ByteArrayInputStream(expanded.getBytes(StandardCharsets.UTF_8)),PASSWORD,staging,escapePlain.length,()->false)){check(Arrays.equals(escapePlain,Files.readAllBytes(decoded.file().toPath())),"fully escaped base64 at exact decoded budget");}
   fails(old,"wrong-password-only".toCharArray(),staging,maximum,"wrong password rejected");
   String tamper=text.replaceFirst("ciphertext\":\".","ciphertext\":\"!");fails(tamper.getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"invalid base64 rejected");
   String ciphertext=text.substring(text.indexOf("\"ciphertext\":\"")+14,text.length()-2);byte[] tag=Base64.getDecoder().decode(ciphertext);tag[tag.length-1]^=1;fails(text.replace(ciphertext,Base64.getEncoder().encodeToString(tag)).getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"tampered tag rejected before expose");
   fails(Arrays.copyOf(old,old.length-8),PASSWORD,staging,maximum,"truncated envelope rejected");
   fails(text.replace("\"version\":1","\"version\":1,\"version\":1").getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"duplicate metadata rejected");
   fails((text+" {}").getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"trailing JSON rejected");
   fails(text.replace("\"version\":1","\"version\":2").getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"unknown version rejected");
   fails(old,PASSWORD,staging,1,"decoded byte budget enforced");
   fails(text.replace("\"version\":1","\"version\":1,\"unexpected\":true").getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"unknown metadata rejected");
   fails(text.replace("apex-encrypted-backup","x".repeat(2048)).getBytes(StandardCharsets.UTF_8),PASSWORD,staging,maximum,"oversized metadata rejected");
   AtomicInteger calls=new AtomicInteger();boolean cancelled=false;try(var ignored=StreamingEncryptedBackup.decrypt(new ByteArrayInputStream(old),PASSWORD,staging,maximum,()->calls.incrementAndGet()>4)){}catch(InterruptedIOException e){cancelled=true;}check(cancelled&&Objects.requireNonNull(staging.list()).length==0,"cancellation leaves no staging");
   if(args.length>1){int megabytes=Integer.parseInt(args[1]);Path large=root.resolve("large-synthetic.bin");try(var out=Files.newOutputStream(large)){byte[] block=new byte[1048576];new Random(1234).nextBytes(block);for(int i=0;i<megabytes;i++)out.write(block);}try(var source=Files.newInputStream(large);var encrypted=StreamingEncryptedBackup.encrypt(source,PASSWORD,staging,maximum,()->false);var bytes=new FileInputStream(encrypted.file());var decrypted=StreamingEncryptedBackup.decrypt(bytes,PASSWORD,staging,maximum,()->false)){check(Arrays.equals(digest(large),digest(decrypted.file().toPath())),megabytes+"MiB full JSON/base64/GCM pipeline bounded-memory roundtrip");System.out.println("Encrypted envelope bytes "+encrypted.file().length());
    boolean midCancelled=false;try(var again=new FileInputStream(encrypted.file());var ignored=StreamingEncryptedBackup.decrypt(again,PASSWORD,staging,maximum,()->Objects.requireNonNull(staging.listFiles()).length>=4&&Arrays.stream(Objects.requireNonNull(staging.listFiles())).anyMatch(f->!f.equals(encrypted.file())&&!f.equals(decrypted.file())&&f.length()>0&&f.length()<1048576))){ }catch(InterruptedIOException e){midCancelled=true;}check(midCancelled,"cancellation while decrypting removes partial plaintext");}Files.delete(large);}
   Path legacyJson=root.resolve("legacy-with-image.json");Files.writeString(legacyJson,"{\"scope\":\"single_company_data_export\",\"schema_version\":7,\"records\":[{\"data\":{\"image_data_url\":\""+"A".repeat(65536)+"\"}}]}");check(com.apexbooks.backup.BackupFormat.inspect(legacyJson.toFile(),1_000_000)==com.apexbooks.backup.BackupFormat.Kind.LEGACY_JSON,"legacy JSON image data is scanned without materializing a giant token");Files.delete(legacyJson);
   check(Objects.requireNonNull(staging.list()).length==0,"all returned private files deleted on close");System.out.println("TOTAL "+checks+" checks; no network/upload operations");
  }finally{Files.deleteIfExists(staging.toPath());}
 }
}
